command_line:
set +e
cat > tiny.wdl <<'EOF'
version 1.0
workflow tiny {
  call hello
  output { String msg = hello.msg }
}
task hello {
  command <<<
    echo hello > out.txt
  >>>
  output { String msg = read_string("out.txt") }
  runtime { docker: "ubuntu:20.04" }
}
EOF
java -Dconfig.file=/dev/null -jar "/jetstream2/scratch/main/jobs/79144267/inputs/dataset_086dbc3d-5766-4dd5-bb5f-3c7556dbafb1.dat" run tiny.wdl > cromwell.stdout 2> cromwell.stderr
run_status=$$?
find cromwell-executions -maxdepth 5 -type f | sort > files.txt 2>/dev/null
{
  echo "run_status=$$run_status"
  echo '--- stdout ---'
  sed -n '1,160p' cromwell.stdout
  echo '--- stderr ---'
  sed -n '1,220p' cromwell.stderr
  echo '--- files ---'
  sed -n '1,120p' files.txt
} > probe.txt
exit 0
